import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d as h,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"浸没成像的矢量分析","description":"","frontmatter":{"title":"浸没成像的矢量分析","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/immersion-vector-imaging.md","filePath":"litho/immersion-vector-imaging.md","lastUpdated":1789023840000}'),d={name:"litho/immersion-vector-imaging.md"};function E(A,a,c,_,C,T){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="浸没成像的矢量分析" tabindex="-1">浸没成像的矢量分析 <a class="header-anchor" href="#浸没成像的矢量分析" aria-label="Permalink to &quot;浸没成像的矢量分析&quot;">​</a></h1><div class="epigraph"><p>水把 $n\\sin\\theta$ 送到 1.35，同一节距对应更大的光线夹角；TM 税和界面 Fresnel 一起写进矢量 TCC，不是把干式标量核乘上 1.44。</p><footer>—— $\\mathrm{NA}=n\\sin\\theta$ 见 Born &amp; Wolf；浸没矢量成像对照 Mack、Levinson 与 Flagello 分层模型</footer></div><p><a href="/litho/scalar-breakdown-high-na">上一课</a>标明标量 \\(|U|^2\\) 在高 NA 失效。缺口是：浸没不是「把空气换成水之后标量核自动变细」，而是<strong>夹角、偏振、水–胶–BARC 界面</strong>同时改传递。主干已有<a href="/litho/arf-immersion">ArF 浸没</a>与<a href="/litho/high-n-immersion">高 n 浸没液</a>的产线史；本课只做成像计算上的矢量分析。像差如何吃 NILS，留给<a href="/litho/aberration-nils-sensitivity">下一课</a>。不重推 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像方 \\(\\mathrm{NA}=n\\sin\\theta\\)。水 \\(n\\approx 1.44\\) 让同一横向频率 \\(n\\sin\\theta/\\lambda\\) 对应更大的 \\(\\theta\\)。标量理论会说截止外推了、Airy 变瘦；矢量理论说 TM 对的点积更差，密线对比可能<strong>不如</strong>按截止外推所期待的那样好。干式 0.93 的「矢量修正」在 1.35 上变成默认项。</p><p>缺口因此是把浸没写进已经建立的 TCC/SOCS：流体折射率进传播与光瞳映射，偏振通道进核，分层薄膜进每条角谱的 Fresnel——而不是把干式标量 PSF 缩放 \\(1/n\\)。</p><h3 id="水层不是又一块玻璃" tabindex="-1">水层不是又一块玻璃 <a class="header-anchor" href="#水层不是又一块玻璃" aria-label="Permalink to &quot;水层不是又一块玻璃&quot;">​</a></h3><p>最后透镜、水、胶顶，三层折射率台阶。s/p 透射不同，胶内驻波节点随角和偏振移。浸没头保证的是均匀水膜；光学模型假定膜厚稳定，气泡与水印是缺陷，不是矢量核的一部分。本课不重写喷淋。</p><p><span class="marginnote">Hyper-NA / High-NA EUV 是反射光学另一套 \\(n=1\\) 的大角度，机制同类（矢量 + 掩模 3D），介质不是水。不要把浸没矢量分析抄成 EUV 的水层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>角谱：每个源点、每个偏振，把平面波按水中 \\(\\mathbf{k}\\) 传到胶，用薄膜矩阵（后课展开）得到胶内 \\(\\mathbf{E}\\)，再 \\(|E|^2\\) 加权吸收。对源积分即矢量 Abbe；预计算即矢量 TCC。SOCS 对本征核同样成立，只是 \\(K\\) 通常更大。</p><p>照明偏振：密线走 TE，让电场平行于线条。<a href="/litho/te-tm-polarization">TE/TM 课</a>的对比差在浸没下放大。二维孔无法两向同时最优，浸没孔层往往更早逼近矢量地板。</p>',12)),(e(),s(p,null,{default:i(()=>[m(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E6%B0%B4%E7%9A%84%20n%22%5D%20--%3E%20ANG%5B%22%E5%90%8C%E4%B8%80%E9%A2%91%E7%8E%87%20%E2%86%92%20%E6%9B%B4%E5%A4%A7%20%CE%B8%22%5D%0A%20%20ANG%20--%3E%20TM%5B%22TM%20%E7%82%B9%E7%A7%AF%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ANG%20--%3E%20FR%5B%22%E7%95%8C%E9%9D%A2%20s%2Fp%20Fresnel%22%5D%0A%20%20TM%20--%3E%20VTCC%5B%22%E7%9F%A2%E9%87%8F%20TCC%20%2F%20%E8%83%B6%E5%86%85%E8%83%BD%E9%87%8F%22%5D%0A%20%20FR%20--%3E%20VTCC%0A%20%20POL%5B%22%E7%85%A7%E6%98%8E%E5%81%8F%E6%8C%AF%22%5D%20--%3E%20VTCC%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="焦深与偏振税不要合成一个-k2" tabindex="-1">焦深与偏振税不要合成一个 k₂ <a class="header-anchor" href="#焦深与偏振税不要合成一个-k2" aria-label="Permalink to &quot;焦深与偏振税不要合成一个 k₂&quot;">​</a></h3><p>\\(\\mathrm{DOF}\\propto\\lambda/\\mathrm{NA}^2\\) 仍描述离焦二次相位的轴向窗。TM 损失在 \\(z=0\\) 已征收。把浸没后「窗变瘦」全部记成 \\(k_2\\)，会把偏振与薄膜角谱误写成调焦问题。下一课把像差敏感度放在矢量像的 NILS 上，正是为避免这种记账。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>横向波矢 \\(k_\\perp=2\\pi n\\sin\\theta/\\lambda\\) 由节距决定。\\(n\\) 增大若 \\(\\theta\\) 跟着增大，\\(k_\\perp\\) 才增大——镜头必须按新 \\(\\mathrm{NA}\\) 设计，灌水不会把旧干式 NA 乘上 \\(n\\)。矢量机制：\\(\\theta\\) 大，\\(E\\) 不平行，干涉项小；同时胶内有效 PSF 随偏振裂成两只不完全重合的核，疏密偏差和孔椭圆化都会改。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假定水的 \\(n\\) 已知、吸收可忽略、无气泡。第二代高 \\(n\\) 流体未量产，不在这里编折射率。标量 OPC 在浸没层靠校准存活的部分，换偏振模式或换 BARC 角谱后必须重校准。禁止引用未公开的 1.35 镜头矢量误差表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>浸没提高的是 \\(n\\sin\\theta\\)，也提高 TM 税与界面角谱。</li><li>矢量 TCC 替换标量核，SOCS 仍可用。</li><li>不要缩放干式 Airy 来当浸没 PSF。</li><li>偏振税不是焦深；孔比线更早付二维矢量账。</li><li>下一课：像差在这条矢量像上怎样打 NILS。</li><li>出处：Born &amp; Wolf；Mack；Levinson；Flagello。</li></ul>',8))])}const u=o(d,[["render",E]]);export{b as __pageData,u as default};
